 "content": "from math import gcd
from functools import reduce


def _rotate_cw(a):
    return [list(row) for row in zip(*a[::-1])]


def _orientations(a):
    for reflected in (False, True):
        b = [row[:] for row in a]
        if reflected:
            b = [row[::-1] for row in b]
        for _ in range(4):
            yield b
            b = _rotate_cw(b)


def _runs(vals):
    lengths = []
    n = 0
    for v in vals:
        if v:
            n += 1
        elif n:
            lengths.append(n)
            n = 0
    if n:
        lengths.append(n)
    return lengths


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    key_pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] not in (0, 8)]
    obj_pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 8]
    kr0, kr1 = min(r for r,c in key_pts), max(r for r,c in key_pts)
    kc0, kc1 = min(c for r,c in key_pts), max(c for r,c in key_pts)
    key = [row[kc0:kc1+1] for row in g[kr0:kr1+1]]
    or0, or1 = min(r for r,c in obj_pts), max(r for r,c in obj_pts)
    oc0, oc1 = min(c for r,c in obj_pts), max(c for r,c in obj_pts)
    pts = set(obj_pts)
    lens = []
    for r in range(or0, or1+1):
        lens += _runs([((r,c) in pts) for c in range(oc0, oc1+1)])
    for c in range(oc0, oc1+1):
        lens += _runs([((r,c) in pts) for r in range(or0, or1+1)])
    scale = reduce(gcd, lens)
    rows, cols = (or1-or0+1)//scale, (oc1-oc0+1)//scale
    mask = [[all((r*scale+or0+i, c*scale+oc0+j) in pts
                 for i in range(scale) for j in range(scale))
             for c in range(cols)] for r in range(rows)]
    keymask = [[v != 0 for v in row] for row in key]
    chosen = None
    for oriented in _orientations(key):
        if [[v != 0 for v in row] for row in oriented] == mask:
            chosen = oriented
            break
    if chosen is None:
        raise ValueError('key and object masks do not align')
    for r in range(rows):
        for c in range(cols):
            color = chosen[r][c]
            if color:
                for i in range(scale):
                    for j in range(scale):
                        g[or0+r*scale+i][oc0+c*scale+j] = color
    return g
